import{_ as t,o,c as s,a3 as a}from"./chunks/framework.DhF4LrUq.js";const i="/shipperdog/snapshot/screenshots/console-notifications.png",g=JSON.parse('{"title":"Route notifications","description":"Route notifications - subscribe roles and channels to domain events, test the pipeline, and read the delivery log.","frontmatter":{"description":"Route notifications - subscribe roles and channels to domain events, test the pipeline, and read the delivery log."},"headers":[],"relativePath":"how-to/console/notifications.md","filePath":"how-to/console/notifications.md"}'),r={name:"how-to/console/notifications.md"};function n(d,e,c,h,l,p){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="route-notifications" tabindex="-1">Route notifications <a class="header-anchor" href="#route-notifications" aria-label="Permalink to &quot;Route notifications&quot;">​</a></h1><p>The <strong>Notifications</strong> screen is your routing table for domain events: which events go to which channel and recipients — the in-app inbox, email, a signed webhook, or the chat channels. Beside it, the delivery ledger records every attempt.</p><p><img src="'+i+'" alt="The Notifications screen"></p><h2 id="create-a-subscription" tabindex="-1">Create a subscription <a class="header-anchor" href="#create-a-subscription" aria-label="Permalink to &quot;Create a subscription&quot;">​</a></h2><ol><li><p>Open <strong>Notifications</strong> and click <strong>New subscription</strong>.</p></li><li><p>Pick the <strong>Events</strong> — from the frozen vocabulary that ships with the platform: <code>ARTIFACT_UPLOADED</code>, <code>ARTIFACT_VALIDATED</code>, <code>ARTIFACT_FAILED</code>, <code>TESTER_DOWNLOADED</code>, <code>RELEASE_CREATED</code>, <code>RELEASE_TRANSITIONED</code>, <code>APPROVAL_REQUESTED</code>, <code>RELEASE_APPROVED</code>, <code>RELEASE_PROMOTED</code>, <code>TESTER_INVITED</code>, <code>FEEDBACK_RECEIVED</code>, <code>FEEDBACK_MARKED_CRITICAL</code>, and <code>AUDIT_EVENT</code> (the SIEM bridge). Subscribe one subscription to as many as it should carry.</p></li><li><p>Pick the <strong>Channel</strong>:</p><ul><li><strong>In-app inbox</strong> — messages surface in the Console for the chosen recipients.</li><li><strong>Email</strong> — the classic.</li><li><strong>Webhook (signed)</strong> — an HTTPS receiver of yours; ShipperDog signs every delivery.</li><li><strong>Slack</strong> / <strong>Microsoft Teams</strong> — a channel webhook URL.</li></ul></li><li><p>Name the recipients:</p><ul><li>Inbox and email take <strong>Recipient roles</strong> (a multi-select; anyone holding the role hears about it) and optionally <strong>Recipient user ids</strong>.</li><li>The webhook family takes the channel&#39;s <strong>webhook URL</strong> and, on creation, a <strong>Signing secret</strong> (16+ characters) — the key your receiver verifies deliveries with. When editing, a blank secret keeps the standing one; set a new value to rotate.</li></ul></li><li><p>Save. New subscriptions are born enabled; the <strong>Enabled</strong> switch in the editor is the parking switch — a disabled subscription routes nothing but keeps its shape.</p></li></ol><h2 id="test-before-you-trust" tabindex="-1">Test before you trust <a class="header-anchor" href="#test-before-you-trust" aria-label="Permalink to &quot;Test before you trust&quot;">​</a></h2><p><strong>Send test</strong> on a subscription pushes one synthetic event through the <em>real</em> channel pipeline — not a mock. Success confirms end-to-end; failure renders the error inline (&quot;the delivery log below carries the retry schedule&quot;) and the ledger gains the row.</p><h2 id="read-the-delivery-ledger" tabindex="-1">Read the delivery ledger <a class="header-anchor" href="#read-the-delivery-ledger" aria-label="Permalink to &quot;Read the delivery ledger&quot;">​</a></h2><p>The log beneath the subscriptions lists every delivery attempt with its status and last error. Failed deliveries retry with backoff and stay visible when exhausted — the integrator&#39;s working list. Park a misbehaving subscription (the <strong>Enabled</strong> switch in its editor) while you fix the receiver, then test again.</p><h2 id="what-to-subscribe-to-as-a-starting-shape" tabindex="-1">What to subscribe to, as a starting shape <a class="header-anchor" href="#what-to-subscribe-to-as-a-starting-shape" aria-label="Permalink to &quot;What to subscribe to, as a starting shape&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You are</th><th>Subscribe</th></tr></thead><tbody><tr><td>Release manager</td><td><code>APPROVAL_REQUESTED</code> (email) — your pending queue grows</td></tr><tr><td>QA lead</td><td><code>FEEDBACK_RECEIVED</code> + <code>FEEDBACK_MARKED_CRITICAL</code> (Slack) — the queue moves</td></tr><tr><td>Security reviewer</td><td><code>FEEDBACK_MARKED_CRITICAL</code> — security reports surface fast</td></tr><tr><td>Compliance</td><td><code>AUDIT_EVENT</code> through the <a href="/shipperdog/snapshot/how-to/console/siem-streams">SIEM stream</a> rather than chat — the durable shape</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Events are identifiers, not prose</p><p>Event payloads carry identifiers and stable vocabularies only — never personal data a listener lacks the authority to read. Route freely; the platform already worried about it.</p></div><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/siem-streams">SIEM streams</a> · <a href="/shipperdog/snapshot/how-to/console/analytics-and-dashboards">dashboards</a> · <a href="/shipperdog/snapshot/roles/org-admin">org-admin quickstart</a></p>',13)])])}const b=t(r,[["render",n]]);export{g as __pageData,b as default};
